    faqChangeEmailA: 'Vai in {profile} > {account} e tocca la matita accanto all\'email.',
    faqChangePasswordQ: 'Come cambio la password?',
    faqChangePasswordA: 'Vai in {profile} > {account} e tocca «{changePassword}» in fondo alla pagina.',
    faqDeleteAccountQ: 'Come elimino il mio account?',
