    faqNoAnswerA: 'Подождите 5 минут и позвоните клиенту. Если он не отвечает, на шаге ввода кода нажмите «{iHaveProblem}», затем «{clientAbsent}».',
    faqWrongAddressQ: 'Неверный адрес',
    faqWrongAddressA: 'Свяжитесь с клиентом с экрана доставки (звонок или сообщение). Если это невозможно, сообщите о проблеме в поддержку, чтобы получить компенсацию.',
    faqAccidentQ: 'Авария во время доставки',
    faqAccidentA: 'Сначала позаботьтесь о своей безопасности. При необходимости вызовите экстренные службы (112), затем сообщите об инциденте в поддержку через приложение.',
    faqDamagedQ: 'Повреждённый заказ',
    faqDamagedA: 'Сфотографируйте повреждённый заказ и сообщите в поддержку. Клиенту вернут деньги, а вас не оштрафуют.',
    faqWhenPaidQ: 'Когда я получу оплату?',
